  //超声波传感器
  ICM_UltrasonicWave(args) {
    //import ultrasonic
    //ICMBP_send(`ICM_ult${DICT_UltrasonicWavePin[args.CHOICE1]}=ultrasonic.ultrasonic_sensor(${DICT_UltrasonicWavePin[args.CHOICE1]})`)
    return ICMBP_read("ICM_ult".concat(DICT_UltrasonicWavePin[args.CHOICE1], ".get()"));
  }
  //检测到摇杆动作
  ICM_RockerType(args) {
    //import joystick
    return ICMBP_read("ICM_joy.".concat(DICT_RockerType[args.CHOICE], "()"));
  }
  //摇杆
  ICM_Rocker(args) {
    //import joystick
    return ICMBP_read("ICM_joy.get_".concat(args.CHOICE.toLowerCase(), "()"));
  }

  //-----------------------动作----------------------------------------
  //舵机
  async ICM_server(args) {
    //import servos
    await ICMBP_send("ICM_ser".concat(args.CHOICE, ".write_angle(").concat(args.TEXT, ")"));
  }
  //电机
  async ICM_DCmotor(args) {
    //import DC_motor 
    await ICMBP_send("ICM_dcm".concat(args.CHOICE, ".run(").concat(args.TEXT, ")"));
  }
  //风扇 1开
  async ICM_Fan(args) {
    await ICMBP_send("pin".concat(args.CHOICE1.substring(1), ".write_digital(").concat(DICT_LaserOff[args.CHOICE2], ")"));
  }
  //电磁铁 1开
  async ICM_Elecmagnet(args) {
    await ICMBP_send("pin".concat(args.CHOICE1.substring(1), ".write_digital(").concat(DICT_LaserOff[args.CHOICE2], ")"));
  }

  //读取位置
