window.EditorPreload.onUSBDeviceEvent((status, device, error) => {
  if (status === 'connected') {
    console.log('设备连接:', device);
  } else if (status === 'disconnected') {
    console.warn('设备断开:', device);
    isConnected = false;
    showToast('设备断开');
  } else if (status === 'error') {
    console.error('设备通信错误:', error);
  }
});
