  showToast(message) {
    let duration = arguments.length > 1 && arguments[1] !== undefined ? arguments[1] : 3000;
    // 如果 toast 容器不存在，则创建一个
    let container = document.getElementById('toast-container');
    if (!container) {
      container = document.createElement('div');
      container.id = 'toast-container';
      Object.assign(container.style, {
        position: 'fixed',
        top: '20px',
        right: '20px',
        zIndex: 9999,
        display: 'flex',
        flexDirection: 'column',
        gap: '10px'
      });
      document.body.appendChild(container);
    }

    // 创建 toast 元素
    const toast = document.createElement('div');
    toast.textContent = message;

    // 样式设置
    Object.assign(toast.style, {
      background: '#333',
      color: '#fff',
      padding: '10px 20px',
      borderRadius: '8px',
      boxShadow: '0 2px 8px rgba(0,0,0,0.2)',
      opacity: '0',
      transform: 'translateY(-20px)',
      transition: 'opacity 0.3s ease, transform 0.3s ease',
      maxWidth: '300px'
    });

    // 添加 toast 到容器
    container.appendChild(toast);

    // 强制触发重绘以启用动画
    requestAnimationFrame(() => {
      toast.style.opacity = '1';
      toast.style.transform = 'translateY(0)';
    });

    // 3秒后移除
    setTimeout(() => {
      toast.style.opacity = '0';
      toast.style.transform = 'translateY(-20px)';
      setTimeout(() => {
        toast.remove();
        // 若容器内无子元素则移除容器
        if (container.children.length === 0) {
          container.remove();
        }
      }, 300); // 等动画结束
    }, duration);
  }
  async setVol(args) {
    if (this.mode) {
      this.currentVol = args.ONE;
      let vol = Number(args.ONE);
      if (vol < 0) {
        vol = 0;
      } else if (vol > 10) {
        vol = 10;
      }
      let jsonData = {
        "command": "speaker",
        "params": {
          "mode": 1,
          "vol": vol,
          "name": ''
        }
      };
      // let str0=`${args.TWO.split('.')[0]} = robot.read_wav('/flash/${args.TWO}')\r`
      // let str = `robot.play_music(${args.ONE},${args.TWO.split('.')[0]})\r`;

      let str = JSON.stringify(jsonData);
      if (this.whatSendFun == 'net') {
        if (socket.checkWebSocketStatus() == 4 || socket.checkWebSocketStatus() == 0) {
          console.log('断开连接，尝试重连');
          this.showToast("⚠️ socket断开，尝试重连......");
          let context = [];
          // context.push(str0)
          context.push(str);
          await socket.setSocket(context);
        } else if (socket.checkWebSocketStatus() == 2) {
          // socket.getSocket().send(str0);
          // await new Promise(resolve => setTimeout(resolve, 50));  // 等待1秒
          socket.getSocket().send(str);
          await new Promise(resolve => setTimeout(resolve, 50)); // 等待1秒
        } else if (socket.checkWebSocketStatus() == 1) {
          this.showToast("⚠️ socket正在连接中，请稍后");
          this.runtime.stopAll();
        }
        socket.setLastPostTime(Date.now());
      } else {
        this.channelPort.postMessage(str);
      }
    }
  }
